import random
from fractions import Fraction


def ruin_prob(k, N, p):
    """Chance of reaching N before 0 from k, betting 1 a time."""
    p = Fraction(p)
    q = 1 - p
    if p == q:
        return Fraction(k, N)
    r = q / p
    return (1 - r ** k) / (1 - r ** N)


def ruin_sim(k, N, p, trials, seed):
    rng = random.Random(seed)
    wins = 0
    for _ in range(trials):
        x = k
        while 0 < x < N:
            x += 1 if rng.random() < p else -1
        wins += x == N
    return wins / trials
